//! Animated NumberLine with native labels and effective post-transform queries.
use crate::plot_presentation::NumberLabelOptions;
use crate::{
    AnimationCompositionRequest as Request, AnimationOptions, ContinuationStep, FadeEndpoint,
    LiveContinuation, LiveProgram, LiveSession, ManimGeometryOptions, ManimNumberLine,
    ManimNumberLineOptions, Mobject, RateFunction, Scene, SemanticAnimationCompositionKind as Kind,
    SemanticFadeDirection, Text, TransformToRequest, YELLOW,
};

type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;
pub const RUN_TIME: f64 = 8.8;

pub struct NumberLinePlayback {
    line: ManimNumberLine,
    marker: Mobject,
    title: Mobject,
    caption: Mobject,
    phase: usize,
}

impl LiveContinuation for NumberLinePlayback {
    type Error = String;
    fn resume(&mut self, live: &mut LiveSession<'_>) -> std::result::Result<ContinuationStep, String> {
        self.step(live).map_err(|error| error.to_string())
    }
}

impl NumberLinePlayback {
    fn step(&mut self, live: &mut LiveSession<'_>) -> Result<ContinuationStep> {
        let durations = [0.5, 1.0, 0.5, 1.5, 0.5, 1.2, 0.5, 0.8, 1.5, 0.8];
        let Some(&duration) = durations.get(self.phase) else { return Ok(ContinuationStep::Finished); };
        let options = AnimationOptions::new().run_time(duration).rate_func(RateFunction::Linear);
        let segment = match self.phase {
            0 => live.declare_and_activate_text_write(&self.title, false, options)?,
            1 => live.declare_and_activate_family_reveal(self.line.family(), false, options)?,
            2 => live.declare_and_activate_composition(&Request::Composition {
                kind: Kind::Parallel,
                children: vec![
                    Request::Fade { target: &self.marker, direction: SemanticFadeDirection::In,
                        endpoint: FadeEndpoint::default(), options },
                    Request::TextWrite { target: &self.caption, reverse_member_order: false, options },
                ],
                options,
            }, options)?,
            3 | 5 | 8 => {
                let value = match self.phase { 3 => 0.0, 5 => 3.0, _ => -2.0 };
                let frame = live.effective_number_line_frame(&self.line)?;
                let [x, y] = frame.number_to_point(value)?;
                let target = live.target_editor(&self.marker)?;
                live.set_translation(&target, x, y)?;
                live.declare_and_activate_transform_to(&self.marker, &target, options)?
            }
            7 => {
                let line_target = live.copy_family(self.line.family())?;
                live.shift_family(line_target.root(), 0.0, 0.6)?;
                let marker_target = live.target_editor(&self.marker)?;
                live.shift(&marker_target, 0.0, 0.6)?;
                live.declare_and_activate_composition(&Request::Composition {
                    kind: Kind::Parallel,
                    children: vec![
                        Request::FamilyTransformTo { source: self.line.family(), target_state: line_target.root(), options },
                        Request::TransformTo(TransformToRequest::new(&self.marker, &marker_target, options)),
                    ],
                    options,
                }, options)?
            }
            _ => live.wait_segment(duration)?,
        };
        self.phase += 1;
        Ok(ContinuationStep::Await(segment))
    }
}

pub fn program() -> Result<LiveProgram<NumberLinePlayback>> {
    let mut scene = Scene::new();
    let mut title = scene.text(Text::new("NumberLine: position and direction").with_font_size(28.0))?;
    title.shift(0.0, 3.0)?;
    let mut caption = scene.text(Text::new("Coordinates follow the line").with_font_size(22.0))?;
    caption.shift(0.0, 2.0)?;
    let mut options = ManimNumberLineOptions::new([-4.0, 4.0, 1.0]);
    options.length = Some(8.8);
    let line = scene.number_line(&options)?;
    line.add_numbers(None, &NumberLabelOptions { exclude_zero: false, ..Default::default() })?;
    let [x, y] = line.authored_frame()?.number_to_point(-4.0)?;
    let mut options = ManimGeometryOptions::dot(x, y, 0.11)?;
    options.set_color(YELLOW.red.into(), YELLOW.green.into(), YELLOW.blue.into(), 1.0)?;
    let marker = scene.geometry(options)?;
    Ok(scene.into_live_program(NumberLinePlayback { line, marker, title, caption, phase: 0 })?)
}

#![cfg(all(feature = "native-text", feature = "bundled-fonts"))]
use noon::{LiveContinuation, LiveProgram, LiveProgramStatus, RustHostCallbackTable, YELLOW};

fn drive<C: LiveContinuation<Error = String>>(program: &mut LiveProgram<C>, time: f64) {
    let mut callbacks = RustHostCallbackTable::new();
    for _ in 0..64 {
        match program.status() {
            LiveProgramStatus::ReadyToResume => { program.resume().unwrap(); }
            LiveProgramStatus::PublicationPending(_) => {
                let context = program.take_renderer_publication().context();
                program.admit_publication(context).unwrap();
            }
            LiveProgramStatus::Awaiting(_) => {
                if (program.session().frame().time - time).abs() < 1e-9 { return; }
                program.drive_to(&mut callbacks, time).unwrap();
            }
            LiveProgramStatus::Finished => return,
            other => panic!("unexpected status {other:?}"),
        }
    }
    panic!("plotting continuation did not reach {time}");
}

#[test]
fn animated_coordinates_admit_in_order_then_finish_the_wait() {
    let mut program = noon::coordinate_plotting_example::program().unwrap();
    for (time, count) in [(0.25, 1), (0.9, 15), (2.3, 16), (3.8, 17)] {
        drive(&mut program, time);
        assert_eq!(program.session().frame().objects.len(), count);
    }
    drive(&mut program, noon::coordinate_plotting_example::RUN_TIME);
    assert_eq!(program.status(), LiveProgramStatus::Finished);
}

#[test]
fn marker_uses_completed_live_number_line_frame_after_transform() {
    let mut program = noon::animated_number_line_example::program().unwrap();
    for (time, x, y) in [(2.75, -2.2, 0.0), (4.6, 1.65, 0.0),
                         (6.1, 3.3, 0.3), (7.25, 0.55, 0.6), (8.8, -2.2, 0.6)] {
        drive(&mut program, time);
        let marker = program.session().frame().objects.iter()
            .find(|object| object.style.fill == Some(YELLOW)).unwrap();
        assert!((f64::from(marker.transform.translation.x) - x).abs() < 2e-5);
        assert!((f64::from(marker.transform.translation.y) - y).abs() < 2e-5);
    }
    assert_eq!(program.status(), LiveProgramStatus::Finished);
    assert_eq!(program.session().frame().objects.len(), 22);
}
